let pool=Q("SELECT p.*,u.phone FROM profiles p JOIN users u ON u.id=p.user_id WHERE u.status='active' AND p.suspended=0").all().map(p=>({...p,ids:JSON.parse(p.caps),sv:JSON.parse(p.svc||'[]')}));
