pool.forEach(p=>p.tier=tierOf(p));const MIN=6,cnt=t=>pool.filter(p=>p.tier===t).length,used=[0];
if(region){if(cnt(0)<MIN&&dist)used.push(1);if(cnt(0)+(used.includes(1)?cnt(1):0)<MIN)used.push(2)}
