for(const g of groups){let rest=pool.filter(p=>p.tier*10+(2-p.band)===g);const seenCap=new Set(),seenD=new Set();while(rest.length&&out.length<limit){let bi=0,bs=-1;rest.forEach((p,i)=>{const s=p.pre+W.div*(.5*(seenCap.has(p.ids[0])?0:1)+.5*(seenD.has(p.district)?0:1));if(s>bs){bs=s;bi=i}});const p=rest.splice(bi,1)[0];seenCap.add(p.ids[0]);seenD.add(p.district);out.push(p)}}
