const live=new Set(Q("SELECT p.pid FROM profiles p JOIN users u ON u.id=p.user_id WHERE u.status='active' AND p.suspended=0").all().map(r=>r.pid));
let epoch=d.epoch,cur=d.current?JSON.parse(d.current):null,snap=d.snapshot?JSON.parse(d.snapshot):null;const refresh=url.searchParams.get('refresh')==='1'||t-d.last_active>IDLE_MS,save=()=>Q('UPDATE devices SET epoch=?,current=?,last_active=? WHERE id=?').run(epoch,JSON.stringify(cur),t,dv);
if(!snap||(live.size&&!snap.some(x=>live.has(x)))){epoch=0;cur=snap=rank({dv,epoch:0,limit:100}).list.map(p=>p.pid);Q('UPDATE devices SET snapshot=? WHERE id=?').run(JSON.stringify(snap),dv);save()}
